/* This code abstracts over different python interpreters by providing
traits for the classes/methods we need and implementations on the bindings objects
from bindgen.

Note this code is unaware of copying memory from the target process, so the
pointer addresses here refer to locations in the target process memory space.
This means we can't dereference them directly.
*/

#![allow(clippy::unnecessary_cast)]

// these bindings are automatically generated by rust bindgen
// using the generate_bindings.py script
use crate::python_bindings::{
    v2_7_15, v3_10_0, v3_11_0, v3_12_0, v3_13_0, v3_14_0, v3_14_0t, v3_15_0, v3_15_0t, v3_3_7,
    v3_5_5, v3_6_6, v3_7_0, v3_8_0, v3_9_5,
};
use crate::python_data_access::{PY_TPFLAGS_BYTES_SUBCLASS, PY_TPFLAGS_STRING_SUBCLASS};

pub trait InterpreterState: Copy {
    type ThreadState: ThreadState;
    type Object: Object;
    type StringObject: StringObject;
    type ListObject: ListObject;
    type TupleObject: TupleObject;
    const HAS_GIL_RUNTIME_STATE: bool = false;

    /// Get offset to a pointer to a pointer to PyThreadState.
    fn threads_head_offset() -> usize;
    /// Get a remote pointer to a pointer to PyObject being the modules dict.
    fn imports_modules_offset() -> usize;
}

pub trait ThreadState: Copy {
    type FrameObject: FrameObject;
    type InterpreterState: InterpreterState;

    fn interp(&self) -> *mut Self::InterpreterState;

    // starting in python 3.11, there is an extra level of indirection
    // in getting the frame. this returns the address
    fn frame_address(&self) -> Option<usize>;

    fn frame(&self, offset: Option<usize>) -> *mut Self::FrameObject;
    fn thread_id(&self) -> u64;
    fn native_thread_id(&self) -> Option<u64>;
    fn next(&self) -> *mut Self;
}

pub trait FrameObject: Copy {
    type CodeObject: CodeObject;

    fn code(&self) -> *mut Self::CodeObject;
    fn lasti(&self) -> i32;
    fn back(&self) -> *mut Self;
    fn is_entry(&self) -> bool;
    fn is_python_frame(&self) -> bool;
}

pub trait CodeObject: Copy + Object {
    type StringObject: StringObject;
    type BytesObject: BytesObject;
    type TupleObject: TupleObject;

    fn name(&self) -> *mut Self::StringObject;
    fn filename(&self) -> *mut Self::StringObject;
    fn line_table(&self) -> *mut Self::BytesObject;
    fn first_lineno(&self) -> i32;
    fn nlocals(&self) -> i32;
    fn argcount(&self) -> i32;
    fn varnames(&self) -> *mut Self::TupleObject;

    fn get_line_number(&self, lasti: i32, table: &[u8]) -> i32;

    /// Returns the qualified name (co_qualname) if available (Python 3.11+).
    /// For older Python versions, returns None.
    fn qualname(&self) -> Option<*mut Self::StringObject>;
}

pub trait BytesObject: Copy {
    fn size(&self) -> usize;
    fn address(&self, base: usize) -> usize;
}

pub trait StringObject: Copy + Object {
    /// The `tp_flags` bit set on subclasses of this string type
    const SUBCLASS_FLAG: usize;

    fn ascii(&self) -> bool;
    fn kind(&self) -> u32;
    fn size(&self) -> usize;
    fn address(&self, base: usize) -> usize;
}

pub trait TupleObject: Copy {
    fn size(&self) -> usize;
    fn address(&self, base: usize, index: usize) -> usize;
}

pub trait ListObject: Copy {
    type Object: Object;
    fn size(&self) -> usize;
    fn item(&self) -> *mut *mut Self::Object;
}

pub trait Object: Copy {
    type TypeObject: TypeObject;
    fn ob_type(&self) -> *mut Self::TypeObject;
}

pub trait TypeObject: Copy {
    fn name(&self) -> *const ::std::os::raw::c_char;
    fn dictoffset(&self) -> isize;
    fn flags(&self) -> usize;
}

/// Acts like a compile time 'if' statement on a python version - evaluates to '$newer' if
/// the python version is at least v3_15_0, and `$older` otherwise
macro_rules! if_python_3_15_or_later {
    (v3_15_0, $newer: expr, $older: expr) => {
        $newer
    };
    (v3_15_0t, $newer: expr, $older: expr) => {
        $newer
    };
    ($py: ident, $newer: expr, $older: expr) => {
        $older
    };
}

macro_rules! if_python_3_14_or_later {
    (v3_14_0, $newer: expr, $older: expr) => {
        $newer
    };
    (v3_14_0t, $newer: expr, $older: expr) => {
        $newer
    };
    ($py: ident, $newer: expr, $older: expr) => {
        if_python_3_15_or_later!($py, $newer, $older)
    };
}

macro_rules! if_python_3_13_or_later {
    (v3_13_0, $newer: expr, $older: expr) => {
        $newer
    };
    ($py: ident, $newer: expr, $older: expr) => {
        if_python_3_14_or_later!($py, $newer, $older)
    };
}

macro_rules! if_python_3_12_or_later {
    (v3_12_0, $newer: expr, $older: expr) => {
        $newer
    };
    ($py: ident, $newer: expr, $older: expr) => {
        if_python_3_13_or_later!($py, $newer, $older)
    };
}

macro_rules! if_python_3_11_or_later {
    (v3_11_0, $newer: expr, $older: expr) => {
        $newer
    };
    ($py: ident, $newer: expr, $older: expr) => {
        if_python_3_12_or_later!($py, $newer, $older)
    };
}

macro_rules! if_python_3_10_or_later {
    (v3_10_0, $newer: expr, $older: expr) => {
        $newer
    };
    ($py: ident, $newer: expr, $older: expr) => {
        if_python_3_11_or_later!($py, $newer, $older)
    };
}

macro_rules! if_python_3 {
    (v2_7_15, $newer: expr, $older: expr) => {
        $older
    };
    ($py: ident, $newer: expr, $older: expr) => {
        $newer
    };
}

macro_rules! string_object_type {
    (v2_7_15) => {
        v2_7_15::PyStringObject
    };
    ($py: ident) => {
        $py::PyUnicodeObject
    };
}

macro_rules! bytes_object_type {
    (v2_7_15) => {
        v2_7_15::PyStringObject
    };
    ($py: ident) => {
        $py::PyBytesObject
    };
}

macro_rules! frame_object_type {
    (v3_15_0) => {
        v3_15_0::_PyInterpreterFrame
    };
    (v3_15_0t) => {
        v3_15_0t::_PyInterpreterFrame
    };
    (v3_14_0) => {
        v3_14_0::_PyInterpreterFrame
    };
    (v3_14_0t) => {
        v3_14_0t::_PyInterpreterFrame
    };
    (v3_13_0) => {
        v3_13_0::_PyInterpreterFrame
    };
    (v3_12_0) => {
        v3_12_0::_PyInterpreterFrame
    };
    (v3_11_0) => {
        v3_11_0::_PyInterpreterFrame
    };
    ($py: ident) => {
        $py::PyFrameObject
    };
}

// Common implementation of all python interpreter traits
macro_rules! implement_interpreter_traits {
    ($py: ident) => {
        impl InterpreterState for $py::PyInterpreterState {
            type ThreadState = $py::PyThreadState;
            type Object = $py::PyObject;
            type StringObject = string_object_type!($py);
            type ListObject = $py::PyListObject;
            type TupleObject = $py::PyTupleObject;
            const HAS_GIL_RUNTIME_STATE: bool = if_python_3_12_or_later!($py, true, false);

            fn threads_head_offset() -> usize {
                // note: on free-threaded versions of python on windows, this offset
                // will not be correct - so we use the version from the _Py_DebugOffsets
                // instead
                if_python_3_11_or_later!(
                    $py,
                    std::mem::offset_of!($py::PyInterpreterState, threads.head),
                    std::mem::offset_of!($py::PyInterpreterState, tstate_head)
                )
            }

            fn imports_modules_offset() -> usize {
                if_python_3_12_or_later!(
                    $py,
                    std::mem::offset_of!($py::PyInterpreterState, imports.modules),
                    std::mem::offset_of!($py::PyInterpreterState, modules)
                )
            }
        }

        impl ThreadState for $py::PyThreadState {
            type FrameObject = frame_object_type!($py);
            type InterpreterState = $py::PyInterpreterState;

            fn frame_address(&self) -> Option<usize> {
                if_python_3_11_or_later!(
                    $py,
                    if_python_3_13_or_later!($py, None, {
                        // python 3.11/3.12
                        const OFFSET: usize = std::mem::offset_of!($py::_PyCFrame, current_frame);
                        Some(self.cframe as usize + OFFSET)
                    }),
                    None
                )
            }
            fn frame(&self, _addr: Option<usize>) -> *mut Self::FrameObject {
                if_python_3_13_or_later!($py, self.current_frame, {
                    if_python_3_11_or_later!(
                        $py,
                        _addr.unwrap() as *mut Self::FrameObject,
                        self.frame
                    )
                })
            }
            fn thread_id(&self) -> u64 {
                self.thread_id as u64
            }
            fn native_thread_id(&self) -> Option<u64> {
                if_python_3_11_or_later!($py, Some(self.native_thread_id as u64), None)
            }
            fn next(&self) -> *mut Self {
                self.next
            }
            fn interp(&self) -> *mut Self::InterpreterState {
                self.interp
            }
        }

        impl FrameObject for frame_object_type!($py) {
            type CodeObject = $py::PyCodeObject;

            fn code(&self) -> *mut Self::CodeObject {
                if_python_3_14_or_later!(
                    $py,
                    {
                        let bits = unsafe { self.f_executable.bits };
                        (bits & !($py::Py_TAG_BITS as usize)) as *mut $py::PyCodeObject
                    },
                    {
                        if_python_3_13_or_later!(
                            $py,
                            self.f_executable as *mut $py::PyCodeObject,
                            self.f_code
                        )
                    }
                )
            }
            fn lasti(&self) -> i32 {
                if_python_3_11_or_later!(
                    $py,
                    {
                        let co_code = self.code() as *const u8;
                        if_python_3_13_or_later!(
                            $py,
                            unsafe { (self.instr_ptr as *const u8).offset_from(co_code) as i32 },
                            unsafe { (self.prev_instr as *const u8).offset_from(co_code) as i32 }
                        )
                    },
                    self.f_lasti as i32
                )
            }
            fn back(&self) -> *mut Self {
                if_python_3_11_or_later!($py, self.previous, self.f_back)
            }

            fn is_entry(&self) -> bool {
                // https://github.com/python/cpython/pull/108036#issuecomment-1684458828
                if_python_3_14_or_later!(
                    $py,
                    self.owner as $py::_frameowner == $py::_frameowner_FRAME_OWNED_BY_INTERPRETER,
                    if_python_3_12_or_later!(
                        $py,
                        self.owner as $py::_frameowner == $py::_frameowner_FRAME_OWNED_BY_CSTACK,
                        if_python_3_11_or_later!($py, self.is_entry != 0, true)
                    )
                )
            }

            fn is_python_frame(&self) -> bool {
                #[allow(unused_variables)]
                let owner = if_python_3_12_or_later!($py, self.owner as $py::_frameowner, self);
                let valid_frame = if_python_3_14_or_later!(
                    $py,
                    if_python_3_15_or_later!(
                        $py,
                        // python 3.15 https://github.com/python/cpython/blob/v3.15.0/Modules/_remote_debugging/frames.c#L167-L188
                        owner != $py::_frameowner_FRAME_OWNED_BY_INTERPRETER,
                        // python 3.14 https://github.com/python/cpython/blob/v3.14.0/Modules/_remote_debugging_module.c#L2134-L2148
                        owner != $py::_frameowner_FRAME_OWNED_BY_INTERPRETER
                            && owner != $py::_frameowner_FRAME_OWNED_BY_CSTACK
                    ),
                    if_python_3_12_or_later!(
                        $py,
                        // python 3.12/3.13
                        // https://github.com/python/cpython/blob/v3.12.0/Python/ceval.c#L688-L692
                        // https://github.com/python/cpython/blob/v3.13.0/Modules/_testexternalinspection.c#L502-L525
                        owner != $py::_frameowner_FRAME_OWNED_BY_CSTACK,
                        true
                    )
                );

                !self.code().is_null() && valid_frame
            }
        }

        impl CodeObject for $py::PyCodeObject {
            type BytesObject = bytes_object_type!($py);
            type StringObject = string_object_type!($py);
            type TupleObject = $py::PyTupleObject;

            fn name(&self) -> *mut Self::StringObject {
                self.co_name as *mut Self::StringObject
            }
            fn filename(&self) -> *mut Self::StringObject {
                self.co_filename as *mut Self::StringObject
            }
            fn line_table(&self) -> *mut Self::BytesObject {
                if_python_3_10_or_later!($py, self.co_linetable, self.co_lnotab)
                    as *mut Self::BytesObject
            }
            fn first_lineno(&self) -> i32 {
                self.co_firstlineno
            }
            fn nlocals(&self) -> i32 {
                self.co_nlocals
            }
            fn argcount(&self) -> i32 {
                self.co_argcount
            }
            fn varnames(&self) -> *mut Self::TupleObject {
                if_python_3_11_or_later!($py, self.co_localsplusnames, self.co_varnames)
                    as *mut Self::TupleObject
            }

            fn get_line_number(&self, lasti: i32, table: &[u8]) -> i32 {
                if_python_3_11_or_later!(
                    $py,
                    compact_get_line_number(
                        self,
                        lasti - std::mem::offset_of!(Self, co_code_adaptive) as i32,
                        table
                    ),
                    if_python_3_10_or_later!(
                        $py,
                        python_3_10_get_line_number(self, lasti, table),
                        legacy_get_line_number(self, lasti, table)
                    )
                )
            }

            fn qualname(&self) -> Option<*mut Self::StringObject> {
                if_python_3_11_or_later!(
                    $py,
                    Some(self.co_qualname as *mut Self::StringObject),
                    None
                )
            }
        }

        impl StringObject for string_object_type!($py) {
            const SUBCLASS_FLAG: usize =
                if_python_3!($py, PY_TPFLAGS_STRING_SUBCLASS, PY_TPFLAGS_BYTES_SUBCLASS);

            fn ascii(&self) -> bool {
                if_python_3!($py, self._base._base.state.ascii() != 0, true)
            }
            fn size(&self) -> usize {
                if_python_3!($py, self._base._base.length as usize, self.ob_size as usize)
            }
            fn kind(&self) -> u32 {
                if_python_3!($py, self._base._base.state.kind(), 1)
            }

            fn address(&self, base: usize) -> usize {
                if_python_3!(
                    $py,
                    {
                        if self._base._base.state.compact() == 0 {
                            return unsafe { self.data.any as usize };
                        }

                        if self._base._base.state.ascii() == 1 {
                            base + std::mem::size_of::<$py::PyASCIIObject>()
                        } else {
                            base + std::mem::size_of::<$py::PyCompactUnicodeObject>()
                        }
                    },
                    base + std::mem::offset_of!(Self, ob_sval)
                )
            }
        }

        impl BytesObject for bytes_object_type!($py) {
            fn size(&self) -> usize {
                if_python_3!($py, self.ob_base.ob_size as usize, self.ob_size as usize)
            }
            fn address(&self, base: usize) -> usize {
                base + std::mem::offset_of!(Self, ob_sval)
            }
        }

        impl TupleObject for $py::PyTupleObject {
            fn size(&self) -> usize {
                if_python_3!($py, self.ob_base.ob_size as usize, self.ob_size as usize)
            }
            fn address(&self, base: usize, index: usize) -> usize {
                base + std::mem::offset_of!(Self, ob_item)
                    + index * std::mem::size_of::<*mut $py::PyObject>()
            }
        }

        impl ListObject for $py::PyListObject {
            type Object = $py::PyObject;
            fn size(&self) -> usize {
                if_python_3!($py, self.ob_base.ob_size as usize, self.ob_size as usize)
            }
            fn item(&self) -> *mut *mut Self::Object {
                self.ob_item
            }
        }

        impl Object for $py::PyObject {
            type TypeObject = $py::PyTypeObject;
            fn ob_type(&self) -> *mut Self::TypeObject {
                self.ob_type as *mut Self::TypeObject
            }
        }

        impl Object for string_object_type!($py) {
            type TypeObject = $py::PyTypeObject;

            fn ob_type(&self) -> *mut Self::TypeObject {
                if_python_3!($py, self._base._base.ob_base.ob_type, self.ob_type)
            }
        }

        impl Object for $py::PyCodeObject {
            type TypeObject = $py::PyTypeObject;
            fn ob_type(&self) -> *mut Self::TypeObject {
                if_python_3_11_or_later!(
                    $py,
                    self.ob_base.ob_base.ob_type,
                    if_python_3!($py, self.ob_base.ob_type, self.ob_type)
                )
            }
        }

        impl TypeObject for $py::PyTypeObject {
            fn name(&self) -> *const ::std::os::raw::c_char {
                self.tp_name
            }
            fn dictoffset(&self) -> isize {
                self.tp_dictoffset
            }
            fn flags(&self) -> usize {
                self.tp_flags as usize
            }
        }
    };
}

implement_interpreter_traits!(v3_15_0);
implement_interpreter_traits!(v3_15_0t);
implement_interpreter_traits!(v3_14_0);
implement_interpreter_traits!(v3_14_0t);
implement_interpreter_traits!(v3_13_0);
implement_interpreter_traits!(v3_12_0);
implement_interpreter_traits!(v3_11_0);
implement_interpreter_traits!(v3_10_0);
implement_interpreter_traits!(v3_9_5);
implement_interpreter_traits!(v3_8_0);
implement_interpreter_traits!(v3_7_0);
implement_interpreter_traits!(v3_6_6);
implement_interpreter_traits!(v3_5_5);
implement_interpreter_traits!(v3_3_7);
implement_interpreter_traits!(v2_7_15);

/// Dispatches to various templatized function calls taking a InterpreterState,
/// by matching the an input Version struct
macro_rules! dispatch_by_version {
    ($version: expr, $free_threaded: expr, $function: ident, $($args:tt)*) => {{
        use crate::python_bindings::{
            v2_7_15, v3_10_0, v3_11_0, v3_12_0, v3_13_0, v3_14_0, v3_15_0, v3_3_7, v3_5_5,
            v3_6_6, v3_7_0, v3_8_0, v3_9_5, v3_14_0t, v3_15_0t,
        };

        use crate::version::Version;

        if $free_threaded {
            match $version {
                Version {
                    major: 3,
                    minor: 14,
                    ..
                } => $function::<v3_14_0t::_is, P>($($args)*),
                Version {
                    major: 3,
                    minor: 15,
                    ..
                } => $function::<v3_15_0t::_is, P>($($args)*),
                _ => Err(format_err!("Unsupported free-threaded version of Python: {}", $version)),
            }
        } else {
            match $version {
                Version {
                    major: 2, minor: 3..=7, ..
                } => $function::<v2_7_15::_is, P>($($args)*),
                Version {
                    major: 3, minor: 3, ..
                } => $function::<v3_3_7::_is, P>($($args)*),
                Version {
                    major: 3, minor: 4..=5, ..
                } => $function::<v3_5_5::_is, P>($($args)*),
                Version {
                    major: 3, minor: 6, ..
                } => $function::<v3_6_6::_is, P>($($args)*),
                Version {
                    major: 3, minor: 7, ..
                } => $function::<v3_7_0::_is, P>($($args)*),
                Version {
                    major: 3, minor: 8, ..
                } => $function::<v3_8_0::_is, P>($($args)*),
                Version {
                    major: 3, minor: 9, ..
                } => $function::<v3_9_5::_is, P>($($args)*),
                Version { major: 3, minor: 10, ..
                } => $function::<v3_10_0::_is, P>($($args)*),
                Version {
                    major: 3, minor: 11, ..
                } => $function::<v3_11_0::_is, P>($($args)*),
                Version {
                    major: 3,
                    minor: 12,
                    ..
                } => $function::<v3_12_0::_is, P>($($args)*),
                Version {
                    major: 3,
                    minor: 13,
                    ..
                } => $function::<v3_13_0::_is, P>($($args)*),
                Version {
                    major: 3,
                    minor: 14,
                    ..
                } => $function::<v3_14_0::_is, P>($($args)*),
                Version {
                    major: 3,
                    minor: 15,
                    ..
                } => $function::<v3_15_0::_is, P>($($args)*),
                _ => Err(format_err!("Unsupported version of Python: {}", $version)),
            }
        }
    }}
}
pub(crate) use dispatch_by_version;

// Lookup line numbers for python 3.11+
fn compact_get_line_number<C: CodeObject>(code: &C, lasti: i32, table: &[u8]) -> i32 {
    // unpack compressed table format from python 3.11+
    // https://github.com/python/cpython/pull/91666/files
    let mut line_number: i32 = code.first_lineno();
    let mut bytecode_address: i32 = 0;

    let mut index: usize = 0;
    loop {
        if index >= table.len() {
            break;
        }
        let byte = table[index];
        index += 1;

        let delta = ((byte & 7) as i32) + 1;
        bytecode_address += delta * 2;
        let code = (byte >> 3) & 15;
        let line_delta = match code {
            15 => 0,
            14 => {
                let delta = read_signed_varint(&mut index, table).unwrap_or(0);
                read_varint(&mut index, table); // end line
                read_varint(&mut index, table); // start column
                read_varint(&mut index, table); // end column
                delta
            }
            13 => read_signed_varint(&mut index, table).unwrap_or(0),
            10..=12 => {
                index += 2; // start column / end column
                (code - 10).into()
            }
            _ => {
                index += 1; // column
                0
            }
        };
        line_number += line_delta as i32;
        if bytecode_address > lasti {
            break;
        }
    }
    line_number
}

// Lookup line numbers for python 3.10
fn python_3_10_get_line_number<C: CodeObject>(code: &C, lasti: i32, table: &[u8]) -> i32 {
    // in Python 3.10 we need to double the lasti instruction value here (and no I don't know why)
    // https://github.com/python/cpython/blob/7b88f63e1dd4006b1a08b9c9f087dd13449ecc76/Python/ceval.c#L5999
    // Whereas in python versions up to 3.9 we didn't.
    // https://github.com/python/cpython/blob/3.9/Python/ceval.c#L4713-L4714
    let lasti = 2 * lasti as i32;

    // unpack the line table. format is specified here:
    // https://github.com/python/cpython/blob/3.10/Objects/lnotab_notes.txt
    let size = table.len();
    let mut i = 0;
    let mut line_number: i32 = code.first_lineno();
    let mut bytecode_address: i32 = 0;
    while (i + 1) < size {
        let delta: u8 = table[i];
        let line_delta: i8 = table[i + 1] as i8;
        i += 2;

        if line_delta == -128 {
            continue;
        }

        line_number += i32::from(line_delta);
        bytecode_address += i32::from(delta);
        if bytecode_address > lasti {
            break;
        }
    }

    line_number
}

// Lookup line numbers for python 3.9 and earlier
fn legacy_get_line_number<C: CodeObject>(code: &C, lasti: i32, table: &[u8]) -> i32 {
    let lasti = lasti as i32;

    // unpack the line table. format is specified here:
    // https://github.com/python/cpython/blob/3.9/Objects/lnotab_notes.txt
    let size = table.len();
    let mut i = 0;
    let mut line_number: i32 = code.first_lineno();
    let mut bytecode_address: i32 = 0;
    while (i + 1) < size {
        bytecode_address += i32::from(table[i]);
        if bytecode_address > lasti {
            break;
        }

        let mut increment = i32::from(table[i + 1]);
        // Handle negative line increments in the line number table - as shown here:
        // https://github.com/python/cpython/blob/143a97f6/Objects/lnotab_notes.txt#L48-L49
        if increment >= 0x80 {
            increment -= 0x100;
        }
        line_number += increment;
        i += 2;
    }
    line_number
}

fn read_varint(index: &mut usize, table: &[u8]) -> Option<usize> {
    if *index >= table.len() {
        return None;
    }
    let mut ret: usize;
    let mut byte = table[*index];
    let mut shift = 0;
    *index += 1;
    ret = (byte & 63) as usize;

    while byte & 64 != 0 {
        if *index >= table.len() {
            return None;
        }
        byte = table[*index];
        *index += 1;
        shift += 6;
        ret += ((byte & 63) as usize) << shift;
    }
    Some(ret)
}

fn read_signed_varint(index: &mut usize, table: &[u8]) -> Option<isize> {
    let unsigned_val = read_varint(index, table)?;
    if unsigned_val & 1 != 0 {
        Some(-((unsigned_val >> 1) as isize))
    } else {
        Some((unsigned_val >> 1) as isize)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_py3_11_line_numbers() {
        use crate::python_bindings::v3_11_0::PyCodeObject;
        let code = PyCodeObject {
            co_firstlineno: 4,
            ..Default::default()
        };

        let table = [
            128_u8, 0, 221, 4, 8, 132, 74, 136, 118, 209, 4, 22, 212, 4, 22, 208, 4, 22, 208, 4,
            22, 208, 4, 22,
        ];
        assert_eq!(code.get_line_number(214, &table), 5);
    }

    #[test]
    fn test_compact_line_number_boundaries() {
        let table = [
            240, 3, 1, 1, 1, 242, 2, 3, 1, 17, 240, 12, 0, 7, 11, 217, 4, 11, 136, 66, 134, 75,
        ];
        let code = v3_14_0::PyCodeObject {
            co_firstlineno: 1,
            ..Default::default()
        };
        let code_offset = std::mem::offset_of!(v3_14_0::PyCodeObject, co_code_adaptive) as i32;
        for (start, end, line) in [(0, 2, 0), (2, 8, 1), (8, 10, 7), (10, 30, 8)] {
            for offset in (start..end).step_by(2) {
                assert_eq!(
                    code.get_line_number(code_offset + offset, &table),
                    line,
                    "incorrect line for bytecode offset {}",
                    offset
                );
            }
        }
    }

    #[test]
    fn test_py3_11_qualname() {
        use crate::python_bindings::v3_11_0::PyCodeObject;
        let code = PyCodeObject {
            co_firstlineno: 1,
            ..Default::default()
        };
        assert!(code.qualname().is_some());
    }

    #[test]
    fn test_py3_10_qualname_not_available() {
        use crate::python_bindings::v3_10_0::PyCodeObject;
        let code = PyCodeObject {
            co_firstlineno: 1,
            ..Default::default()
        };
        assert!(code.qualname().is_none());
    }
}
